+            .templateId("43e30abc-4193-9620-8888")
+            .templateName("Test Template")
+            .remark("Test Remark")
+            .version("1.0")
+            .createDate(System.currentTimeMillis())
+            .creator("Test Creator")
+            .modifyDate(System.currentTimeMillis())
+            .modifier("Test Modifier")
+            .status("Undeployed")
+            .templateType("Test Type")
+            .cover("Test Cover")
+            .catalogs("Test Catalogs")
+            .build();
+
+        reportTemplateDao.insert(testData);
+    }
+
+    // --- 测试 insert 方法 ---
+    @Test
+    public void testInsert() throws ServiceException {
+        // Given
+        ReportTemplatePO newTemplate = ReportTemplatePO.builder()
+            .templateId("43e30abc-4193-9620-7aa7")
+            .templateName("New Test Template")
+            .remark("New Test Remark")
+            .version("1.0")
+            .createDate(System.currentTimeMillis())
+            .creator("New Test Creator")
+            .modifyDate(System.currentTimeMillis())
+            .modifier("New Test Modifier")
+            .status("Undeployed")
+            .templateType("New Test Type")
+            .cover("New Test Cover")
+            .catalogs("New Test Catalogs")
+            .build();
+
+        // When
+        reportTemplateDao.insert(newTemplate);
+
+        // Then
+        ReportTemplatePO result = reportTemplateDao.selectByTemplateId(newTemplate.getTemplateId());
+        assertNotNull(result);
+        assertEquals(newTemplate.getTemplateName(), result.getTemplateName());
+        assertEquals(newTemplate.getRemark(), result.getRemark());
+        assertEquals(newTemplate.getVersion(), result.getVersion());
+        assertEquals(newTemplate.getCreator(), result.getCreator());
+        assertEquals(newTemplate.getModifier(), result.getModifier());
+        assertEquals(newTemplate.getStatus(), result.getStatus());
+        assertEquals(newTemplate.getTemplateType(), result.getTemplateType());
+        assertEquals(newTemplate.getCover(), result.getCover());
+        assertEquals(newTemplate.getCatalogs(), result.getCatalogs());
+    }
+
+    // --- 测试 insert 方法，传入 null 参数 ---
+    @Test
+    public void testInsertWithNull() throws ServiceException {
+        // When
+        reportTemplateDao.insert(null);
+
+        // Then
+        // 不抛出异常即为成功
+    }
+
+    // --- 测试 insert 方法，模拟数据库异常 ---
