+
+        // Then
+        assertNotNull(result);
+        assertEquals(testData.getTemplateId(), result.getTemplateId());
+        assertEquals(testData.getTemplateName(), result.getTemplateName());
+        assertEquals(testData.getRemark(), result.getRemark());
+        assertEquals(testData.getVersion(), result.getVersion());
+        assertEquals(testData.getCreator(), result.getCreator());
+        assertEquals(testData.getModifier(), result.getModifier());
+        assertEquals(testData.getStatus(), result.getStatus());
+        assertEquals(testData.getTemplateType(), result.getTemplateType());
+        assertEquals(testData.getCover(), result.getCover());
+        assertEquals(testData.getCatalogs(), result.getCatalogs());
+    }
