+        assertEquals(updatedTemplate.getCreator(), updatedResult.getCreator());
+        assertEquals(updatedTemplate.getModifier(), updatedResult.getModifier());
+        assertEquals(updatedTemplate.getStatus(), updatedResult.getStatus());
+        assertEquals(updatedTemplate.getTemplateType(), updatedResult.getTemplateType());
+        assertEquals(updatedTemplate.getCover(), updatedResult.getCover());
+        assertEquals(updatedTemplate.getCatalogs(), updatedResult.getCatalogs());
+    }
