+    // --- 测试 updateStatusWithDeployed 方法，传入 null 参数 ---
+    @Test
+    public void testUpdateStatusWithDeployedWithNull() throws ServiceException {
+        // When
+        reportTemplateDao.updateStatusWithDeployed(null);
