+    // --- 测试 updateStatusWithUndeployed 方法 ---
+    @Test
+    public void testUpdateStatusWithUndeployed() throws ServiceException {
+        // Given
+        testData.setStatus("Deployed");
+
+        // When
+        reportTemplateDao.updateStatusWithUndeployed(testData);
+
+        // Then
+        ReportTemplatePO result = reportTemplateDao.selectByTemplateId(testData.getTemplateId());
+        assertNotNull(result);
+        assertEquals("Undeployed", result.getStatus());
