+
+    // --- 测试 updateStatusWithUndeployed 方法，传入 null 参数 ---
+    @Test
+    public void testUpdateStatusWithUndeployedWithNull() throws ServiceException {
+        // When
+        reportTemplateDao.updateStatusWithUndeployed(null);
