+-- 素材管理表：用于存储会话素材
+CREATE TABLE `TBL_NL2SQL_CONVERSATION_MATERIAL_LIBRARIES` (
+    id VARCHAR(36) NOT NULL,
+    conversationId VARCHAR(36) NOT NULL,
+    chatId VARCHAR(36) NULL,
+    question VARCHAR(850) NOT NULL,
+    dataset CLOB NULL,
+    summary CLOB NULL,
+    nl2sql CLOB NULL,
+    originData CLOB NULL,
+    eChartsData CLOB NULL,
+    imageBase64 CLOB NULL,
+    createTime BIGINT NOT NULL,
+    PRIMARY KEY (id)
+);
+
+CREATE INDEX TBL_NL2SQL_CONVERSATION_MATERIAL_LIBRARIESID ON TBL_NL2SQL_CONVERSATION_MATERIAL_LIBRARIES (conversationId);
+
+-- 报告模板表：用于管理报告模板
+CREATE TABLE `TBL_NL2REPORT_CONVERSATION_REPORT_TEMPLATE` (
+    templateId VARCHAR(32) NOT NULL,
+    templateName VARCHAR(32) NOT NULL,
+    remark VARCHAR(128) NULL,
+    version VARCHAR(32) NULL,
+    createDate BIGINT NULL,
+    creator VARCHAR(32) NULL,
+    modifyDate BIGINT NULL,
+    modifier VARCHAR(32) NULL,
+    status VARCHAR(32) NOT NULL,
+    templateType VARCHAR(32) NOT NULL,
+    cover CLOB NOT NULL,
+    catalogs CLOB NOT NULL,
+    PRIMARY KEY (templateId)
+);
+
+CREATE INDEX TBL_NL2REPORT_CONVERSATION_REPORT_TEMPLATEID ON TBL_NL2REPORT_CONVERSATION_REPORT_TEMPLATE (templateId);
